package sandboxcreate

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"runtime"
	"strings"

	apiclientgen "github.com/discobox-ai/discobox/api/gen"
	apimodel "github.com/discobox-ai/discobox/api/model"
	"github.com/discobox-ai/discobox/cli/internal/gitunborn"
	"github.com/discobox-ai/discobox/cli/internal/origin"
	"github.com/discobox-ai/discobox/internal/hostid"
	"github.com/discobox-ai/discobox/internal/originkey"
	"github.com/discobox-ai/discobox/platform"
	"github.com/discobox-ai/discobox/sandboxpath"
	"github.com/discobox-ai/x/gitutil"
	"github.com/discobox-ai/x/id"
)

const (
	runSourceKindGit       = "git"
	runWorkspaceModeClean  = "clean"
	runWorkspaceModeDirty  = "dirty"
	runSourceRefTypeBranch = "branch"
	runSourceRefTypeTag    = "tag"
	runSourceRefTypeCommit = "commit"
	runSnapshotRefPrefix   = "refs/discobox/run/"
	// defaultRunSourceName is the subdirectory of the sandbox's working root a
	// source with no host path of its own to keep goes in, and where the
	// discobox starts (defaultRunSourceDir).
	defaultRunSourceName = "source"
	defaultRemoteBranch  = "HEAD"
	// wslDriveRoot is where WSL mounts the Windows drives, and so where a
	// Windows host path is mirrored to inside a sandbox.
	wslDriveRoot = "/mnt"
	// maxRunSourceSlugLen is the API's slug limit.
	maxRunSourceSlugLen      = 63
	runSnapshotCommitMessage = "discobox new workspace snapshot\n"
	runEmptyBaseMessage      = "discobox new empty base\n"
)

// IncludeDirty decides whether uncommitted local work is carried into the
// sandbox as a workspace snapshot. It implements pflag.Value so frontends can
// bind it directly to a --include-dirty flag.
type IncludeDirty string

const (
	// IncludeDirtyAuto asks the user when the local workspace is dirty.
	IncludeDirtyAuto IncludeDirty = "auto"
	// IncludeDirtyAlways always snapshots a dirty local workspace.
	IncludeDirtyAlways IncludeDirty = "true"
	// IncludeDirtyNever starts from the checked-out commit and leaves
	// uncommitted work behind.
	IncludeDirtyNever IncludeDirty = "false"
)

func (m *IncludeDirty) String() string { return string(*m) }

func (m *IncludeDirty) Type() string { return "true|false|auto" }

func (m *IncludeDirty) Set(value string) error {
	switch IncludeDirty(strings.ToLower(strings.TrimSpace(value))) {
	case "":
		*m = IncludeDirtyAuto
	case IncludeDirtyAuto:
		*m = IncludeDirtyAuto
	case IncludeDirtyAlways, "yes", "y", "1":
		*m = IncludeDirtyAlways
	case IncludeDirtyNever, "no", "n", "0":
		*m = IncludeDirtyNever
	default:
		return fmt.Errorf("invalid value %q: want true, false, or auto", value)
	}
	return nil
}

// DirtyWorkspace describes the uncommitted work found in a local source repo,
// so a frontend can show it while asking whether to include it.
type DirtyWorkspace struct {
	RepoRoot   string
	BaseCommit string
	Changes    []gitutil.StatusChange
}

// ConfirmIncludeDirtyFunc asks the user whether to carry a dirty workspace into
// the sandbox. A nil func means nobody can be asked, and the uncommitted work is
// included rather than silently dropped.
type ConfirmIncludeDirtyFunc func(context.Context, DirtyWorkspace) (bool, error)

// DirectoryCopy describes a source directory that is in no Git repository, so a
// frontend can ask whether to copy it into the sandbox. Everything in such a
// directory is uncommitted work, so the whole of it is what the answer decides
// about.
type DirectoryCopy struct {
	Dir string
	// Size is counting what copying would carry, and keeps counting while the
	// question is on screen: a frontend polls it until it reports Done rather
	// than making the user wait for a number before being asked anything. It
	// stops when the confirmation returns.
	Size *DirectoryWalk
}

// ConfirmCopyDirectoryFunc asks the user whether to copy a directory in no Git
// repository into the sandbox. A nil func means nobody can be asked, and the
// directory is copied rather than a sandbox coming up with nothing in it.
type ConfirmCopyDirectoryFunc func(context.Context, DirectoryCopy) (bool, error)

// runSourceOptions carries the caller's policy for what local content reaches
// the sandbox into source resolution.
type runSourceOptions struct {
	// Platform is the sandbox's, which every path placed in it is judged by
	// (ADR 0145 §6).
	Platform     platform.Platform
	IncludeDirty IncludeDirty
	Confirm      ConfirmIncludeDirtyFunc
	ConfirmCopy  ConfirmCopyDirectoryFunc
}

type resolvedRunSource struct {
	Kind string
	// Slug names this source's repository in the sandbox, and is what a push
	// addresses. It is set only for a source code reference, whose name is the
	// client's to choose; the primary source leaves it to the server, which
	// calls it "primary".
	Slug           string
	URL            string
	LocalDirectory string
	// RepoRoot is where git commands for this source run: the repository root
	// of a local source, and the throwaway repository built over the directory
	// when the directory is in no repository at all.
	RepoRoot string
	// NoLocalRepository states that LocalDirectory holds no repository, so
	// nothing can be cloned from it however reachable it is.
	NoLocalRepository bool
	// NoLocalCommits states that the repository at LocalDirectory has no
	// commits, so a clone of it yields nothing either. Unlike
	// NoLocalRepository the commits are still here afterwards: they were
	// written into the user's own repository (ADR 0083).
	NoLocalCommits bool
	// NoLocalGitDirectory states that the repository at LocalDirectory has no
	// Git directory in place at its .git — a linked worktree or submodule
	// checkout — so there is nothing there a sandbox's origin may be bound to
	// (ADR 0093). Its commits stay here, as NoLocalCommits' do.
	NoLocalGitDirectory bool
	// UpstreamURL is the remote the checked-out branch tracks in the local
	// repository, which the sandbox adds as its upstream remote. Empty when the
	// branch tracks nothing the sandbox could reach (localUpstreamURL).
	UpstreamURL string
	Checkout    resolvedRunSourceCheckout
	Workspace   resolvedRunSourceWorkspace
	Destination resolvedRunSourceDestination
	// cleanup releases the throwaway repository, and is nil for a source that
	// did not need one.
	cleanup func()
}

// LocalSources are the local repositories a create resolved its sources from —
// the primary source and every `--include` reference — and that a push delivers
// those sources out of. Close releases them: a directory with no repository of
// its own got a throwaway one built over it, which is deleted once the source
// has reached the sandbox, and a real repository has nothing to release.
//
// They are carried from create to delivery rather than resolved twice, because
// a throwaway repository cannot be found again: it holds the only copy of the
// base commit and the workspace snapshot that the sandbox was configured
// against.
type LocalSources struct {
	sources []localSource
}

// localSource is one resolved source's repository, addressed by the same key
// the create request filed the source under: empty for the primary source, and
// the source code reference key — the sandbox directory it lands in — for a
// reference.
type localSource struct {
	key      string
	repoRoot string
	cleanup  func()
}

// add records the repository a resolved source was built from. The zero key is
// the primary source.
func (s *LocalSources) add(key string, resolved resolvedRunSource) {
	s.sources = append(s.sources, localSource{key: key, repoRoot: resolved.RepoRoot, cleanup: resolved.cleanup})
}

// Close releases every local source. It is safe to call on a nil value and to
// call more than once, so a caller can defer it and still close early.
func (s *LocalSources) Close() {
	if s == nil {
		return
	}
	for i := range s.sources {
		if s.sources[i].cleanup == nil {
			continue
		}
		s.sources[i].cleanup()
		s.sources[i].cleanup = nil
	}
}

// resolved reports whether resolution produced a source at all. The zero value
// is the answer for a directory in no repository whose copy was declined:
// nothing of it travels, so there is nothing to check out, and the sandbox is
// built with no source the way --no-source asks for outright (ADR 0077 §1).
func (s resolvedRunSource) resolved() bool { return s.Kind != "" }

// close releases the throwaway repository a resolved source built, for the
// paths that fail before it is handed to a LocalSources.
func (s resolvedRunSource) close() {
	if s.cleanup != nil {
		s.cleanup()
	}
}

type resolvedRunSourceCheckout struct {
	Commit  string
	RefName string
	RefType string
}

type resolvedRunSourceWorkspace struct {
	Mode        string
	SnapshotRef string
	BaseCommit  string
}

type resolvedRunSourceDestination struct {
	Directory        string
	WorkingDirectory string
}

func resolveRunSource(ctx context.Context, sourceArg string, opts runSourceOptions) (resolvedRunSource, error) {
	source, ref, explicitRef := splitRunSourceRef(sourceArg)
	if strings.TrimSpace(source) == "" {
		return resolvedRunSource{}, fmt.Errorf("source directory or Git repository is required")
	}
	if IsRemoteGitSource(source) {
		// A remote repository has no working tree, so it has no uncommitted
		// work for --include-dirty to decide about, whatever its value.
		return resolveRemoteRunSource(ctx, source, ref, explicitRef, opts.Platform)
	}
	return resolveLocalRunSource(ctx, source, ref, explicitRef, opts)
}

// OriginKeys are the origin keys `discobox ls` lists for sourceArg (ADR 0111
// §3): the one a discobox cut from sourceArg on this machine is filed under,
// and this machine's own, which files its discoboxes with no source. Any @REF
// suffix is dropped, so every discobox cut from one place shares its key
// whatever ref it checked out.
func OriginKeys(ctx context.Context, sourceArg string) (sourceKey, hostKey string, err error) {
	host, err := hostid.Get()
	if err != nil {
		return "", "", err
	}
	root, err := SourceRoot(ctx, sourceArg)
	if err != nil {
		return "", "", err
	}
	return originkey.Of(host, root), originkey.Host(host), nil
}

// SourceRoot is the root a create from sourceArg records for its primary
// source — what the server's GitSource.Root reads back, and so what an origin
// key hashes: a remote URL in the form the request carries it, and a
// directory's repository root, or the directory itself outside one.
func SourceRoot(ctx context.Context, sourceArg string) (string, error) {
	source, _, _ := splitRunSourceRef(sourceArg)
	source = strings.TrimSpace(source)
	if IsRemoteGitSource(source) {
		return remoteSourceRoot(source), nil
	}
	if source == "" {
		source = "."
	}
	return origin.ProjectPath(ctx, source)
}

// remoteSourceRoot is a remote URL in the form the create request carries it:
// parsed and printed again (apiGitSource), which is the string the server
// stores. A URL that does not parse is left as written; the create refuses it
// before anything is filed under it.
func remoteSourceRoot(source string) string {
	u, err := url.Parse(source)
	if err != nil {
		return source
	}
	return u.String()
}

// LocalProjectDirectory is the directory on this machine a command acting on
// sourceArg works in: a local source's repository root, or the working
// directory's when the source is a remote repository, which has no local
// directory of its own. It is where the launcher keeps its prompt draft and
// reads its branch from. It is not where a discobox is filed; that is its
// origin key.
func LocalProjectDirectory(ctx context.Context, sourceArg string) (string, error) {
	source, _, _ := splitRunSourceRef(sourceArg)
	dir := strings.TrimSpace(source)
	if dir == "" || IsRemoteGitSource(dir) {
		cwd, err := os.Getwd()
		if err != nil {
			return "", fmt.Errorf("resolve working directory: %w", err)
		}
		dir = cwd
	}
	return origin.ProjectPath(ctx, dir)
}

func (s resolvedRunSource) apiGitSource() (*apimodel.GitSource, error) {
	source := &apimodel.GitSource{Kind: apiclientgen.GitSourceKindGit}
	source.SetSlug(optionalString(s.Slug))
	if s.URL != "" {
		u, err := url.Parse(s.URL)
		if err != nil {
			return nil, err
		}
		source.SetURL(apiclientgen.NewOptURI(*u))
	}
	source.SetLocalDirectory(optionalString(s.LocalDirectory))
	if s.NoLocalRepository {
		source.SetNoLocalRepository(apiclientgen.NewOptBool(true))
	}
	if s.NoLocalCommits {
		source.SetNoLocalCommits(apiclientgen.NewOptBool(true))
	}
	if s.NoLocalGitDirectory {
		source.SetNoLocalGitDirectory(apiclientgen.NewOptBool(true))
	}
	source.SetUpstreamUrl(optionalString(s.UpstreamURL))
	checkout := apimodel.GitSourceCheckout{}
	checkout.SetCommit(optionalString(s.Checkout.Commit))
	checkout.SetRefName(optionalString(s.Checkout.RefName))
	checkout.SetRefType(optionalString(s.Checkout.RefType))
	source.SetCheckout(apiclientgen.NewOptGitSourceCheckout(checkout))
	workspace := apimodel.GitSourceWorkspace{}
	switch s.Workspace.Mode {
	case runWorkspaceModeDirty:
		workspace.SetMode(apiclientgen.NewOptGitSourceWorkspaceMode(apiclientgen.GitSourceWorkspaceModeDirty))
	default:
		workspace.SetMode(apiclientgen.NewOptGitSourceWorkspaceMode(apiclientgen.GitSourceWorkspaceModeClean))
	}
	workspace.SetSnapshotRef(optionalString(s.Workspace.SnapshotRef))
	workspace.SetBaseCommit(optionalString(s.Workspace.BaseCommit))
	source.SetWorkspace(apiclientgen.NewOptGitSourceWorkspace(workspace))
	destination := apimodel.GitSourceDestination{}
	destination.SetDirectory(optionalString(s.Destination.Directory))
	destination.SetWorkingDirectory(optionalString(s.Destination.WorkingDirectory))
	source.SetDestination(apiclientgen.NewOptGitSourceDestination(destination))
	return source, nil
}

func resolveLocalRunSource(ctx context.Context, source, ref string, explicitRef bool, opts runSourceOptions) (resolvedRunSource, error) {
	absSource, err := filepath.Abs(source)
	if err != nil {
		return resolvedRunSource{}, fmt.Errorf("resolve source directory: %w", err)
	}
	info, err := os.Stat(absSource)
	if err != nil {
		return resolvedRunSource{}, fmt.Errorf("stat source directory %s: %w", absSource, err)
	}
	if !info.IsDir() {
		return resolvedRunSource{}, fmt.Errorf("source %s is not a directory", absSource)
	}
	repoRoot, err := gitutil.Root(ctx, absSource)
	if errors.Is(err, gitutil.ErrNotARepository) {
		return resolveDirectoryRunSource(ctx, absSource, ref, explicitRef, opts)
	}
	if err != nil {
		return resolvedRunSource{}, err
	}
	noGitDirectory, err := noLocalGitDirectory(repoRoot)
	if err != nil {
		return resolvedRunSource{}, err
	}
	if gitunborn.HeadIsUnborn(ctx, repoRoot) {
		resolved, err := resolveUnbornRunSource(ctx, repoRoot, absSource, ref, explicitRef, opts)
		if err != nil {
			return resolvedRunSource{}, err
		}
		resolved.NoLocalGitDirectory = noGitDirectory
		resolved.UpstreamURL = localUpstreamURL(ctx, repoRoot, resolved.Checkout)
		return resolved, nil
	}
	destination := localRunDestination(opts.Platform, repoRoot, absSource)
	resolved := resolvedRunSource{
		Kind:                runSourceKindGit,
		LocalDirectory:      repoRoot,
		RepoRoot:            repoRoot,
		NoLocalGitDirectory: noGitDirectory,
		Workspace: resolvedRunSourceWorkspace{
			Mode: runWorkspaceModeClean,
		},
		Destination: destination,
	}
	if explicitRef {
		// A snapshot is only ever built on top of HEAD, so an explicit ref and
		// uncommitted work are mutually exclusive rather than silently ignored.
		if opts.IncludeDirty == IncludeDirtyAlways {
			return resolvedRunSource{}, fmt.Errorf("--include-dirty=true cannot be combined with an explicit ref (%s@%s): uncommitted changes only apply on top of the checked-out commit", source, ref)
		}
		commit, err := gitutil.ResolveCommit(ctx, repoRoot, ref)
		if err != nil {
			return resolvedRunSource{}, err
		}
		resolved.Checkout = localRunCheckout(ctx, repoRoot, ref, commit)
		resolved.UpstreamURL = localUpstreamURL(ctx, repoRoot, resolved.Checkout)
		return resolved, nil
	}
	baseCommit, err := gitutil.ResolveCommit(ctx, repoRoot, "HEAD")
	if err != nil {
		return resolvedRunSource{}, err
	}
	resolved.Checkout = localRunCheckout(ctx, repoRoot, "", baseCommit)
	resolved.UpstreamURL = localUpstreamURL(ctx, repoRoot, resolved.Checkout)
	if opts.IncludeDirty == IncludeDirtyNever {
		return resolved, nil
	}
	workspaceTree, cleanup, err := gitutil.CurrentWorkspaceTree(ctx, repoRoot)
	if err != nil {
		return resolvedRunSource{}, err
	}
	defer cleanup()
	if !workspaceTree.Dirty {
		return resolved, nil
	}
	include, err := includeDirtyWorkspace(ctx, repoRoot, workspaceTree.BaseCommit, opts)
	if err != nil {
		return resolvedRunSource{}, err
	}
	if !include {
		return resolved, nil
	}
	workspace, err := snapshotWorkspace(ctx, repoRoot, workspaceTree)
	if err != nil {
		return resolvedRunSource{}, err
	}
	resolved.Workspace = workspace
	return resolved, nil
}

// noLocalGitDirectory reports whether repoRoot's .git is anything other than
// the repository's Git directory itself: a file naming one elsewhere, as a
// linked worktree and a submodule checkout have, a symlink, or nothing at all
// when git found the repository some other way.
//
// A clone-delivered source's origin is bound into the sandbox at exactly
// repoRoot/.git, and never at repoRoot, whose ignored files are the ones a
// developer keeps out of git on purpose (ADR 0093). Following the pointer is not
// the answer: for a worktree it is the main checkout's Git directory, a
// repository the source never named. So this is reported, and the server
// delivers the source by push.
func noLocalGitDirectory(repoRoot string) (bool, error) {
	info, err := os.Lstat(filepath.Join(repoRoot, ".git"))
	if os.IsNotExist(err) {
		return true, nil
	}
	if err != nil {
		return false, fmt.Errorf("stat %s: %w", filepath.Join(repoRoot, ".git"), err)
	}
	return !info.IsDir(), nil
}

// snapshotWorkspace records a dirty working tree as a commit on top of the
// commit it differs from, under a ref of our own so no branch is disturbed. The
// sandbox reads the difference between the two back out as uncommitted changes.
func snapshotWorkspace(ctx context.Context, repoRoot string, tree gitutil.WorkspaceTree) (resolvedRunSourceWorkspace, error) {
	snapshotID, err := id.New(id.PrefixSnapshot)
	if err != nil {
		return resolvedRunSourceWorkspace{}, err
	}
	snapshotCommit, err := gitutil.CommitTree(ctx, repoRoot, tree.Tree, tree.BaseCommit, runSnapshotCommitMessage)
	if err != nil {
		return resolvedRunSourceWorkspace{}, err
	}
	snapshotRef := runSnapshotRefPrefix + snapshotID
	if err := gitutil.UpdateRef(ctx, repoRoot, snapshotRef, snapshotCommit); err != nil {
		return resolvedRunSourceWorkspace{}, err
	}
	return resolvedRunSourceWorkspace{
		Mode:        runWorkspaceModeDirty,
		SnapshotRef: snapshotRef,
		BaseCommit:  tree.BaseCommit,
	}, nil
}

// resolveUnbornRunSource prepares a source from a repository that has no
// commits.
//
// It is the shape ADR 0045 gives a directory in no repository at all, for the
// same reason: nothing has ever been committed, so the working tree is
// uncommitted work — all of it — on a base of nothing. The base is a root
// commit of the empty tree and the working tree is snapshotted on top of it, so
// the sandbox comes up with the files as the uncommitted changes they are
// rather than as a first commit the user did not write.
//
// Unlike that case there is no repository to build: this directory holds one,
// and it is where the base commit, the snapshot, and their refs are written.
// `refs/heads/<branch>` is never touched, so HEAD stays unborn and the user's
// first commit stays theirs; the objects stay reachable, so a later
// `discobox push` can still deliver this source (ADR 0083 §2).
//
// Nobody is asked. The question a directory in no repository gets exists
// because it may be a home directory somebody ran in by accident, and `git
// init` here is the user saying it is not. The dirty-workspace question has
// nothing to offer either: its alternative is the last commit, and there is
// none. `--include-dirty=false` still answers ahead of time, and its answer is
// the empty base commit at the repository's own path.
func resolveUnbornRunSource(ctx context.Context, repoRoot, absSource, ref string, explicitRef bool, opts runSourceOptions) (resolvedRunSource, error) {
	if explicitRef {
		return resolvedRunSource{}, fmt.Errorf("%s has no commits yet, so it has no ref %q to check out", repoRoot, ref)
	}
	branch, ok := gitutil.CurrentBranch(ctx, repoRoot)
	if !ok {
		return resolvedRunSource{}, fmt.Errorf("repository %s has no commits and no branch checked out", repoRoot)
	}
	emptyTree, err := gitutil.EmptyTree(ctx, repoRoot)
	if err != nil {
		return resolvedRunSource{}, err
	}
	baseCommit, err := gitutil.CommitTree(ctx, repoRoot, emptyTree, "", runEmptyBaseMessage)
	if err != nil {
		return resolvedRunSource{}, err
	}
	// The base commit is what the sandbox checks out and what the snapshot is
	// measured against on both ends, so it has to be a ref in this repository
	// rather than a loose object in it: nothing else here points at it, and a
	// delivery that happens later would be racing git's own pruning.
	baseID, err := id.New(id.PrefixSnapshot)
	if err != nil {
		return resolvedRunSource{}, err
	}
	if err := gitutil.UpdateRef(ctx, repoRoot, runSnapshotRefPrefix+baseID, baseCommit); err != nil {
		return resolvedRunSource{}, err
	}
	resolved := resolvedRunSource{
		Kind:           runSourceKindGit,
		LocalDirectory: repoRoot,
		RepoRoot:       repoRoot,
		NoLocalCommits: true,
		Checkout: resolvedRunSourceCheckout{
			Commit:  baseCommit,
			RefName: branch,
			RefType: runSourceRefTypeBranch,
		},
		Workspace:   resolvedRunSourceWorkspace{Mode: runWorkspaceModeClean},
		Destination: localRunDestination(opts.Platform, repoRoot, absSource),
	}
	if opts.IncludeDirty == IncludeDirtyNever {
		return resolved, nil
	}
	tree, cleanup, err := gitunborn.WorkspaceTree(ctx, repoRoot)
	if err != nil {
		return resolvedRunSource{}, err
	}
	defer cleanup()
	if tree == emptyTree {
		// An empty repository. There is nothing to snapshot, and the sandbox
		// starts on the empty base commit at this repository's path — which is
		// what `git init` in a new project directory asks for.
		return resolved, nil
	}
	workspace, err := snapshotWorkspace(ctx, repoRoot, gitutil.WorkspaceTree{
		BaseCommit: baseCommit,
		BaseTree:   emptyTree,
		Tree:       tree,
		Dirty:      true,
	})
	if err != nil {
		return resolvedRunSource{}, err
	}
	resolved.Workspace = workspace
	return resolved, nil
}

// resolveDirectoryRunSource prepares a source from a directory that is in no
// Git repository.
//
// The directory's content is the uncommitted work of a repository that does not
// exist yet, so this builds that repository outside the directory, commits an
// empty root commit as the base, and snapshots the whole directory on top of it
// as a dirty workspace. The sandbox comes up with the directory's files as
// uncommitted changes, which is what they are, and the user's directory is left
// untouched — no .git appears in it, and the repository is deleted once the
// source has been delivered.
//
// The user is asked first, because the answer is not obvious the way it is for
// a repository: a directory in no repository is as likely to be a home
// directory somebody ran `discobox new` in as it is to be a project, and the
// whole of it is what would be carried.
//
// Declining is not a cancel: it resolves to no source at all, the request
// --no-source builds outright (ADR 0077 §1). It is not a repository of nothing
// at the directory's path either — that put an empty checkout over whatever
// lives at that path in the sandbox, which is $HOME in the case the question
// exists to catch. Nothing is built over the directory to reach that answer,
// so declining costs nothing at all.
func resolveDirectoryRunSource(ctx context.Context, dir, ref string, explicitRef bool, opts runSourceOptions) (resolvedRunSource, error) {
	if explicitRef {
		return resolvedRunSource{}, fmt.Errorf("%s is not a Git repository, so it has no ref %q to check out", dir, ref)
	}
	copyContent, err := copyDirectoryContent(ctx, dir, opts)
	if err != nil {
		return resolvedRunSource{}, err
	}
	if !copyContent {
		return resolvedRunSource{}, nil
	}
	repoRoot, cleanup, err := gitutil.InitOverWorkTree(ctx, dir)
	if err != nil {
		return resolvedRunSource{}, err
	}
	resolved, err := directoryRunSource(ctx, dir, repoRoot, opts.Platform)
	if err != nil {
		cleanup()
		return resolvedRunSource{}, err
	}
	resolved.cleanup = cleanup
	return resolved, nil
}

// copyDirectoryContent decides whether the content of a directory in no Git
// repository is carried into the sandbox.
//
// --include-dirty answers it outright, because the directory's content is
// uncommitted work — all of it — and that flag is what says whether uncommitted
// work travels. Otherwise it is the frontend's question, asked against a
// measurement of the directory that is still running while it is on screen. It
// is asked before the repository is built over the directory: indexing a home
// directory takes long enough that doing it first would answer the question by
// making it too late.
//
// With nobody to ask, the content is copied: that is what a source directory
// has always meant, and a sandbox that silently came up empty is the worse
// surprise. An empty directory is not worth asking about either, and answers
// yes: there is nothing in it to carry, and the sandbox that results is a
// workspace at that directory's own path — which is what standing in an empty
// directory and running asks for (ADR 0077 §3).
func copyDirectoryContent(ctx context.Context, dir string, opts runSourceOptions) (bool, error) {
	if opts.IncludeDirty == IncludeDirtyNever {
		return false, nil
	}
	if opts.IncludeDirty != IncludeDirtyAuto || opts.ConfirmCopy == nil {
		return true, nil
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false, fmt.Errorf("read source directory %s: %w", dir, err)
	}
	if len(entries) == 0 {
		return true, nil
	}
