// Package sourceconverge materializes the sandbox's own sources (ADR 0126 §4):
// the runtime-config document says, per source, where its origin is served,
// what is pinned and where the checkout belongs, and the agent converges each
// one onto its target and reports how far it got.
//
// Materializing is convergence, not a verb. A source is cloned, checked out
// and its workspace snapshot restored exactly once, then marked inside its own
// .git (sandboxconfig.SourceMaterializedMarker); every later pass only asserts
// the origin remote, because re-materializing a workspace the sandbox has been
// using would discard its work. git runs as whoever owns the checkout, in the
// sandbox's own namespace, so nothing is chowned after it and no
// safe.directory is needed.
//
// A materialized source is not the ready signal. The pool still reads the
// delivered project layer (ProjectLayer), settles the sandbox's spec, and only
// then says so with the document's Delivered (ADR 0055).
package sourceconverge

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"log/slog"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/discobox-ai/discobox/sandbox-agent/execs"
	"github.com/discobox-ai/discobox/sandboxconfig"
)

// State is how far a source has converged.
type State string

const (
	// StateWaiting is a source with nothing to clone yet: no origin, or an
	// origin the client has not pushed anything into.
	StateWaiting State = "waiting"
	// StateCloning is a source being materialized now.
	StateCloning State = "cloning"
	// StateMaterialized is a source cloned, checked out and restored, once.
	StateMaterialized State = "materialized"
	// StateFailed is a source whose last attempt failed; it is retried.
	StateFailed State = "failed"
)

// SourceState is one source's convergence, as the status poll reports it.
type SourceState struct {
	Slug  string
	State State
	// Commit is the commit checked out, once materialized.
	Commit string
	// Error is why the last attempt failed.
	Error string
	// Revision is the runtime-config revision the state was reached under.
	Revision  int64
	UpdatedAt time.Time
}

// Config is what a Converger needs from the sandbox around it.
type Config struct {
	// Manifest is sandbox.json's sources: how each slug is checked out — its
	// branch or tag, its upstream remote, its workspace snapshot.
	Manifest []sandboxconfig.Source
	// Env is the sandbox's environment, which git runs with so that a clone
	// takes the same route off the box — the pool proxy — a user's git does.
	Env map[string]string
	// User is the sandbox's resolved default user. git runs as the owner of
	// each checkout, and as this user, with its home and groups, when that is
	// who the owner is.
	User *execs.User
	// CredentialHelper is the credential.helper value each origin is
	// configured with, so a fetch — the agent's own and a user's later
	// `git fetch origin` alike — reads the origin's token from this agent.
	// Empty configures none.
	CredentialHelper string
	// RetryInterval is the first wait before a failed or waiting source is
	// tried again; it doubles to MaxRetryInterval. Zero uses the defaults.
	RetryInterval    time.Duration
	MaxRetryInterval time.Duration
	Logger           *slog.Logger
}

const (
	defaultRetryInterval    = 5 * time.Second
	defaultMaxRetryInterval = 2 * time.Minute
	// sourceTimeout bounds one source's materialization, a clone of a large
	// repository through the proxy included.
	sourceTimeout = 30 * time.Minute
)

// Converger converges the sandbox's sources on the last document it was given.
type Converger struct {
	cfg      Config
	manifest map[string]sandboxconfig.Source
	wake     chan struct{}

	mu      sync.Mutex
	desired *sandboxconfig.RuntimeConfig
	// received is when desired arrived, which is when a source not tried
	// yet started waiting.
	received time.Time
	states   map[string]SourceState
}

// New returns a Converger. Nothing happens until Run is running and Converge
// has been given a document.
func New(cfg Config) *Converger {
	if cfg.RetryInterval <= 0 {
		cfg.RetryInterval = defaultRetryInterval
	}
	if cfg.MaxRetryInterval < cfg.RetryInterval {
		cfg.MaxRetryInterval = max(defaultMaxRetryInterval, cfg.RetryInterval)
	}
	if cfg.Logger == nil {
		cfg.Logger = slog.Default()
	}
	manifest := make(map[string]sandboxconfig.Source, len(cfg.Manifest))
	for _, source := range cfg.Manifest {
		manifest[source.Slug] = source
	}
	return &Converger{
		cfg:      cfg,
		manifest: manifest,
		wake:     make(chan struct{}, 1),
		states:   map[string]SourceState{},
	}
}

// Converge makes doc the document to converge on and wakes the loop. It never
// blocks: a document delivered while a pass runs is picked up by the next.
func (c *Converger) Converge(doc sandboxconfig.RuntimeConfig) {
	c.mu.Lock()
	c.desired, c.received = &doc, time.Now().UTC()
	c.mu.Unlock()
	select {
	case c.wake <- struct{}{}:
	default:
	}
}

// Run converges until ctx ends: on every new document, and again after a
// growing interval while any source is failed or waiting on its origin.
func (c *Converger) Run(ctx context.Context) {
	var retry <-chan time.Time
	backoff := c.cfg.RetryInterval
	for {
		select {
		case <-ctx.Done():
			return
		case <-c.wake:
			backoff = c.cfg.RetryInterval
		case <-retry:
		}
		if c.pass(ctx) {
			retry = time.After(backoff)
			backoff = min(backoff*2, c.cfg.MaxRetryInterval)
		} else {
			retry = nil
			backoff = c.cfg.RetryInterval
		}
	}
}

// States reports each source the current document names, in its order.
func (c *Converger) States() []SourceState {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.desired == nil {
		return nil
	}
	out := make([]SourceState, 0, len(c.desired.Sources))
	for _, source := range c.desired.Sources {
		if state, ok := c.states[source.Slug]; ok {
			out = append(out, state)
			continue
		}
		out = append(out, SourceState{Slug: source.Slug, State: StateWaiting, Revision: c.desired.Revision, UpdatedAt: c.received})
	}
	return out
}

// pass converges every source once and reports whether one is worth trying
// again without a new document.
func (c *Converger) pass(ctx context.Context) bool {
	c.mu.Lock()
	doc := c.desired
	c.mu.Unlock()
	if doc == nil {
		return false
	}
	again := false
	for _, source := range doc.Sources {
		if ctx.Err() != nil {
			return false
		}
		state := c.converge(ctx, doc.Revision, source)
		// A source still cloning after its pass was superseded mid-attempt;
		// failed and waiting ones are retried until they converge.
		if state.State == StateFailed || state.State == StateCloning || (state.State == StateWaiting && source.OriginURL != "") {
			again = true
		}
	}
	return again
}

func (c *Converger) setState(state SourceState) SourceState {
	state.UpdatedAt = time.Now().UTC()
	c.mu.Lock()
	c.states[state.Slug] = state
	c.mu.Unlock()
	return state
}

// converge brings one source to its target and records where it got.
func (c *Converger) converge(ctx context.Context, revision int64, source sandboxconfig.RuntimeSource) SourceState {
	state := SourceState{Slug: source.Slug, Revision: revision}
	if source.OriginURL == "" {
		state.State = StateWaiting
		return c.setState(state)
	}
	ctx, cancel := context.WithTimeout(ctx, sourceTimeout)
	defer cancel()
	repo, err := c.open(source.Target)
	if err != nil {
		return c.failed(state, err)
	}
	// Only an origin that takes a token is handed to the agent's helper: the
	// helper configuration clears every other helper for its URL, and a
	// remote-URL source's user may well have their own.
	helper := ""
	if source.OriginToken != "" {
		helper = c.cfg.CredentialHelper
	}
	if commit, ok := materializedAt(source.Target); ok {
		// Once materialized the workspace is the sandbox's: only the origin
		// remote is asserted, since the pool may move where it serves it.
		if err := repo.ensureOrigin(ctx, source.OriginURL, helper); err != nil {
			return c.failed(state, err)
		}
		repo.ensureOriginHeadRef(ctx)
		state.State, state.Commit = StateMaterialized, commit
		return c.setState(state)
	}
	if commit, ok := repo.unmarkedCheckout(ctx); ok {
		// A checkout made before materializing was marked at all — a pool
		// cloned it, from before the marker existed, into a sandbox that has
		// not started since (unmarkedCheckout says how it is told). It is the
		// sandbox's workspace, so it is adopted as it stands rather than
		// refused or cloned over: marked once, at what it has checked out,
		// and from then on like any other.
		if err := repo.ensureOrigin(ctx, source.OriginURL, helper); err != nil {
			return c.failed(state, err)
		}
		if err := repo.writeMarker(filepath.Join(source.Target, ".git", sandboxconfig.SourceMaterializedMarker), commit); err != nil {
			return c.failed(state, err)
		}
		c.cfg.Logger.Info("adopted a source checkout from before the materialized marker", "slug", source.Slug, "target", source.Target, "commit", commit)
		state.State, state.Commit = StateMaterialized, commit
		return c.setState(state)
	}
	state.State = StateCloning
	c.setState(state)
	cloned, err := repo.prepare(ctx, source, c.manifest[source.Slug], helper)
	if err != nil {
		return c.failed(state, err)
	}
	if !cloned {
		state.State = StateWaiting
		return c.setState(state)
	}
	// Marking it materialized is once-only, so it is done only for the source
	// the current document still describes. A document that moved its pin,
	// origin or target while this attempt ran has woken the loop already; the
	// next pass goes on from this checkout to the new pin (the resume path
	// fetches and checks out again), and this one finishes nothing. The check
	// and the marker are one step under the lock that Converge takes.
	c.mu.Lock()
	defer c.mu.Unlock()
	if !c.stillDesired(source) {
		return state
	}
	commit, err := repo.finish(ctx)
	state.UpdatedAt = time.Now().UTC()
	if err != nil {
		state.State, state.Error = StateFailed, err.Error()
		c.states[state.Slug] = state
		return state
	}
	state.State, state.Commit = StateMaterialized, commit
	c.states[state.Slug] = state
	c.cfg.Logger.Info("materialized source", "slug", source.Slug, "target", source.Target, "commit", commit)
	return state
}

// stillDesired reports whether the current document describes source as it
// was when an attempt began: the same target, origin and pin. A new token
// alone does not matter to what was cloned. The caller holds c.mu.
func (c *Converger) stillDesired(source sandboxconfig.RuntimeSource) bool {
	if c.desired == nil {
		return false
	}
	for _, current := range c.desired.Sources {
		if current.Slug == source.Slug {
			return current.Target == source.Target && current.OriginURL == source.OriginURL && current.Commit == source.Commit
		}
	}
	return false
}

func (c *Converger) failed(state SourceState, err error) SourceState {
	state.State, state.Error = StateFailed, err.Error()
	c.cfg.Logger.Warn("materialize source", "slug", state.Slug, "error", err)
	return c.setState(state)
}

// open is the checkout at target, worked on as whoever owns it.
func (c *Converger) open(target string) (*repository, error) {
	info, err := os.Stat(target)
	if err != nil {
		return nil, fmt.Errorf("source target: %w", err)
	}
	if !info.IsDir() {
		return nil, fmt.Errorf("source target %s is not a directory", target)
	}
	return &repository{dir: target, env: c.cfg.Env, owner: c.owner(info)}, nil
}

// owner is the identity to run git as in a directory described by info: this
// process's own when it owns it, the sandbox's resolved user — with its home
// and groups — when that is who does, and otherwise the bare ids.
func (c *Converger) owner(info fs.FileInfo) *execs.User {
	uid, gid, ok := fileOwner(info)
	if !ok || uid == int64(os.Getuid()) {
		return nil
	}
	if user := c.cfg.User; user != nil && user.UID != nil && *user.UID == uid {
		return user.Clone()
	}
	return &execs.User{UID: &uid, GID: &gid}
}

// Token is the bearer token for an origin, matched the way git describes the
// request to a credential helper: scheme, host (with any port) and path. It is
// empty when no source in the current document is served there with one.
func (c *Converger) Token(protocol, host, requestPath string) string {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.desired == nil {
		return ""
	}
	for _, source := range c.desired.Sources {
		if source.OriginToken == "" {
			continue
		}
		origin, err := url.Parse(source.OriginURL)
		if err != nil {
			continue
		}
		if strings.EqualFold(origin.Scheme, protocol) && strings.EqualFold(origin.Host, host) &&
			strings.Trim(origin.Path, "/") == strings.Trim(requestPath, "/") {
			return source.OriginToken
		}
	}
	return ""
}

// ErrUnknownSource is a slug the current document does not name.
var ErrUnknownSource = errors.New("no such source")

// ErrNotMaterialized is a source the sandbox has not materialized yet.
var ErrNotMaterialized = errors.New("source is not materialized")

// ErrInvalidProjectLayer is a project layer file that is not a JSON object of
// a sane size.
var ErrInvalidProjectLayer = errors.New("invalid project layer")

// projectLayerPath is the project layer inside a source's working tree, and
// maxProjectLayer the most of it that is read.
const (
	projectLayerPath = ".discobox/project.json"
	maxProjectLayer  = 1 << 20
)

// ProjectLayer is a materialized source's project layer as the sandbox read it.
type ProjectLayer struct {
	Slug   string
	Commit string
	// Layer is the file's JSON object, nil when the source has none.
	Layer json.RawMessage
}

// ProjectLayer reads slug's .discobox/project.json from its working tree, for
// the pool to settle the sandbox's spec on (ADR 0055). It is read through an
// os.Root at the checkout, so a symlink in the repository cannot point this
// root-run read anywhere outside it.
func (c *Converger) ProjectLayer(ctx context.Context, slug string) (ProjectLayer, error) {
	c.mu.Lock()
	var source *sandboxconfig.RuntimeSource
	if c.desired != nil {
		for i := range c.desired.Sources {
			if c.desired.Sources[i].Slug == slug {
				found := c.desired.Sources[i]
				source = &found
				break
			}
		}
	}
	c.mu.Unlock()
	if source == nil || source.Target == "" {
		return ProjectLayer{}, fmt.Errorf("%w: %q", ErrUnknownSource, slug)
	}
	if _, ok := materializedAt(source.Target); !ok {
		return ProjectLayer{}, fmt.Errorf("%w: %q", ErrNotMaterialized, slug)
	}
	repo, err := c.open(source.Target)
	if err != nil {
		return ProjectLayer{}, err
	}
	out := ProjectLayer{Slug: slug, Commit: repo.head(ctx)}
	root, err := os.OpenRoot(source.Target)
	if err != nil {
		return ProjectLayer{}, err
	}
	defer root.Close()
	file, err := root.Open(projectLayerPath)
	if errors.Is(err, fs.ErrNotExist) {
		return out, nil
	}
	if err != nil {
		return ProjectLayer{}, fmt.Errorf("%w: %w", ErrInvalidProjectLayer, err)
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, maxProjectLayer+1))
	if err != nil {
		return ProjectLayer{}, fmt.Errorf("%w: %w", ErrInvalidProjectLayer, err)
	}
	if len(data) > maxProjectLayer {
		return ProjectLayer{}, fmt.Errorf("%w: %s is over %d bytes", ErrInvalidProjectLayer, projectLayerPath, maxProjectLayer)
	}
	var object map[string]json.RawMessage
	if err := json.Unmarshal(data, &object); err != nil || object == nil {
		return ProjectLayer{}, fmt.Errorf("%w: %s is not a JSON object", ErrInvalidProjectLayer, projectLayerPath)
	}
	out.Layer = data
	return out, nil
}

// materializedAt reports whether the checkout at target carries the marker
// that it has been materialized once, and the commit the marker records — empty
// for a marker a pool wrote, which records none.
func materializedAt(target string) (string, bool) {
	data, err := os.ReadFile(filepath.Join(target, ".git", sandboxconfig.SourceMaterializedMarker))
	if err != nil {
		return "", false
	}
	return strings.TrimSpace(string(data)), true
}

package sourceconverge

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"

	"github.com/discobox-ai/discobox/sandbox-agent/execs"
	"github.com/discobox-ai/discobox/sandboxconfig"
)

// repository is one source's checkout, and who git runs as in it.
type repository struct {
	dir   string
	env   map[string]string
	owner *execs.User
}

const (
	// scratchPrefix names the directory a clone lands in before its .git is
	// moved onto the target, one per attempt. It is inside the target rather
	// than beside it: the target can be a mount point, and a rename does not
	// cross one.
	scratchPrefix = ".discobox-materializing-"
	// scratchOwnedMarker, inside a scratch directory, says this agent made it.
	// Only a directory carrying it is ever removed, so a path in the target
	// that merely shares the prefix is the sandbox's and is left alone.
	scratchOwnedMarker = ".discobox-scratch"
	// materializingMarker marks a .git this agent moved onto the target and
	// has not finished materializing. A .git with neither it nor the
	// materialized marker is not this agent's to touch.
	materializingMarker = "discobox-materializing"
	// upstreamRemote is the remote a source's own upstream is added as. It
	// cannot be origin, which in a sandbox is the pool's origin route.
	upstreamRemote = "upstream"
)

// prepare clones source onto the target, checks it out, restores its
// workspace snapshot and adds its upstream remote — everything but marking it
// materialized, which finish does once the converger has checked the document
// still asks for this. It returns false, having changed nothing, while the
// origin has nothing in it to clone: a push-delivered source before the
// client's push lands.
//
// A clone is never left half-made at the target, which is what would make
// every later attempt fail on a partial .git (#30): it lands in a scratch
// directory and its .git is renamed into place only once it is whole. What
// follows the rename is resumable — the .git carries materializingMarker, and
// a later attempt goes again from the checkout. Every step after the rename
// writes the tracked tree whole (checkout -f, restore) rather than cleaning
// it, so files that were in the target before the clone are never removed,
// on the first attempt or a retry.
//
// helper is empty for an origin that takes no token, so that a remote-URL
// source keeps whatever credential helper its user configures.
func (r *repository) prepare(ctx context.Context, source sandboxconfig.RuntimeSource, spec sandboxconfig.Source, helper string) (bool, error) {
	gitDir := filepath.Join(r.dir, ".git")
	switch _, err := os.Stat(gitDir); {
	case errors.Is(err, os.ErrNotExist):
		cloned, err := r.clone(ctx, source.OriginURL, spec, helper)
		if err != nil || !cloned {
			return false, err
		}
	case err != nil:
		return false, err
	default:
		if _, err := os.Stat(filepath.Join(gitDir, materializingMarker)); err != nil {
			// Someone else's repository: one the sandbox began itself, or a
			// clone interrupted before this agent cloned sources (#30). A
			// pool's finished checkout was adopted before this
			// (unmarkedCheckout). Resetting it would destroy whatever it holds.
			return false, fmt.Errorf("%s already holds a repository this sandbox did not clone", r.dir)
		}
		// An attempt that moved the clone into place and stopped before it
		// finished: the checkout and restore below write the tracked tree
		// whole again, so it goes on from there — after a fetch, since what
		// stopped it may have been a pin the origin did not have yet.
		if err := r.ensureOrigin(ctx, source.OriginURL, helper); err != nil {
			return false, err
		}
		if err := r.run(ctx, nil, "fetch", "origin"); err != nil {
			return false, err
		}
	}
	if err := r.ensureOrigin(ctx, source.OriginURL, helper); err != nil {
		return false, err
	}
	if err := r.checkout(ctx, source.Commit, spec); err != nil {
		return false, err
	}
	if err := r.restoreWorkspace(ctx, spec.Workspace); err != nil {
		return false, err
	}
	if err := r.configureUpstream(ctx, spec.UpstreamURL); err != nil {
		return false, err
	}
	return true, nil
}

// unmarkedCheckout reports whether the target holds a repository with neither
// marker — not materialized, and not an attempt of this agent's — that a pool
// made before it marked what it materialized, and which commit it has checked
// out. A pool's checkout is told by two things a repository someone else put
// there does not have together: a commit checked out, since a pool's clone
// always ended in one, and an origin that is an absolute path on a filesystem
// — the pool's own, or the bind it pointed origin at — never a URL.
func (r *repository) unmarkedCheckout(ctx context.Context) (string, bool) {
	gitDir := filepath.Join(r.dir, ".git")
	if info, err := os.Lstat(gitDir); err != nil || !info.IsDir() {
		return "", false
	}
	if _, err := os.Lstat(filepath.Join(gitDir, materializingMarker)); err == nil {
		return "", false
	}
	origin, err := r.configValues(ctx, "remote.origin.url")
	if err != nil || len(origin) != 1 || (!strings.HasPrefix(origin[0], "/") && !filepath.IsAbs(origin[0])) {
		return "", false
	}
	commit := r.head(ctx)
	return commit, commit != ""
}

// ensureOriginHeadRef gives the checkout an origin/HEAD when it has none,
// from what the origin's HEAD names now. A clone of a pushed origin made the
// moment the push landed, before the pool pointed the origin's HEAD at what
// arrived, has none, and origin/HEAD is the upstream ref a source checked out
// at a bare commit or tag tracks. One that cannot be resolved yet is left for
// a later pass.
func (r *repository) ensureOriginHeadRef(ctx context.Context) {
	if err := r.run(ctx, nil, "rev-parse", "--verify", "--quiet", "refs/remotes/origin/HEAD"); err == nil {
		return
	}
	_ = r.run(ctx, nil, "remote", "set-head", "origin", "--auto")
}

// finish marks a prepared checkout materialized and returns the commit the
// marker records, which is what the source's reported state names from then
// on, whatever the sandbox commits since.
func (r *repository) finish(ctx context.Context) (string, error) {
	gitDir := filepath.Join(r.dir, ".git")
	commit := r.head(ctx)
	if err := r.writeMarker(filepath.Join(gitDir, sandboxconfig.SourceMaterializedMarker), commit); err != nil {
		return "", err
	}
	return commit, os.Remove(filepath.Join(gitDir, materializingMarker))
}

// clone fetches the origin into a scratch directory inside the target and
// moves its .git onto the target, without a checkout: the checkout that
// follows writes the tree. It returns false, cloning nothing, when the origin
// has no refs — asked first, because a clone of an empty origin that names a
// branch fails rather than coming back empty.
func (r *repository) clone(ctx context.Context, originURL string, spec sandboxconfig.Source, helper string) (bool, error) {
	var credentials []string
	if helper != "" {
		// For these two commands only; ensureOrigin then writes the same into
		// the repository for every fetch after them.
		for _, setting := range credentialConfig(originURL, helper) {
			for _, value := range setting.values {
				credentials = append(credentials, "-c", setting.key+"="+value)
			}
		}
	}
	refs, err := r.output(ctx, r.dir, nil, append(slices.Clone(credentials), "ls-remote", "--", originURL)...)
	if err != nil {
		return false, err
	}
	if refs == "" {
		return false, nil
	}
	scratch, err := r.makeScratch()
	if err != nil {
		return false, err
	}
	defer os.RemoveAll(scratch)
	clone := filepath.Join(scratch, "clone")
	args := append(credentials, "clone", "--no-checkout")
	if spec.RefName != "" {
		args = append(args, "--branch", spec.RefName)
	}
	args = append(args, "--", originURL, clone)
	if err := r.run(ctx, nil, args...); err != nil {
		return false, err
	}
	if err := r.writeMarker(filepath.Join(clone, ".git", materializingMarker), ""); err != nil {
		return false, err
	}
	if err := os.Rename(filepath.Join(clone, ".git"), filepath.Join(r.dir, ".git")); err != nil {
		return false, err
	}
	return true, nil
}

// makeScratch removes what earlier attempts left — only directories this
// agent marked as its own — and makes a fresh one, under a name no other
// attempt shares, that the checkout's owner can clone into.
func (r *repository) makeScratch() (string, error) {
	leftovers, err := filepath.Glob(filepath.Join(r.dir, scratchPrefix+"*"))
	if err != nil {
		return "", err
	}
	for _, leftover := range leftovers {
		info, err := os.Lstat(filepath.Join(leftover, scratchOwnedMarker))
		if err != nil || !info.Mode().IsRegular() {
			continue
		}
		if err := os.RemoveAll(leftover); err != nil {
			return "", err
		}
	}
	scratch, err := os.MkdirTemp(r.dir, scratchPrefix)
	if err != nil {
		return "", err
	}
	if err := os.WriteFile(filepath.Join(scratch, scratchOwnedMarker), nil, 0o600); err != nil {
		_ = os.RemoveAll(scratch)
		return "", err
	}
	if r.owner != nil {
		if err := chownTo(scratch, r.owner); err != nil {
			_ = os.RemoveAll(scratch)
			return "", err
		}
	}
	return scratch, nil
}

// checkout writes the working tree at the pinned commit: on the source's
// branch, created there, when it names one, and detached otherwise; with no
// pin, at the ref the clone was asked for, or the clone's own HEAD. It is
// forced, which writes every tracked path whole — over a file the target
// already held at the same path, and over whatever an interrupted attempt
// left — and leaves every other file in the target alone.
func (r *repository) checkout(ctx context.Context, commit string, spec sandboxconfig.Source) error {
	commit = strings.TrimSpace(commit)
	switch {
	case commit != "" && spec.RefName != "" && spec.RefType == "branch":
		return r.run(ctx, nil, "checkout", "--force", "-B", spec.RefName, commit)
	case commit != "":
		return r.run(ctx, nil, "checkout", "--force", "--detach", commit)
	case spec.RefName != "":
		return r.run(ctx, nil, "checkout", "--force", spec.RefName)
	}
	return r.run(ctx, nil, "checkout", "--force", "HEAD")
}

// restoreWorkspace applies a dirty workspace's snapshot to the working tree,
// all unstaged, on top of the branch at its base commit. The snapshot ref is
// fetched explicitly: a clone brings branches and tags, and it is neither.
func (r *repository) restoreWorkspace(ctx context.Context, workspace *sandboxconfig.SourceWorkspace) error {
	if workspace == nil {
		return nil
	}
	base, snapshot := strings.TrimSpace(workspace.BaseCommit), strings.TrimSpace(workspace.SnapshotRef)
	if base == "" || snapshot == "" {
		return errors.New("dirty workspace requires baseCommit and snapshotRef")
	}
	if err := r.run(ctx, nil, "check-ref-format", snapshot); err != nil {
		return fmt.Errorf("invalid workspace snapshot ref %q: %w", snapshot, err)
	}
	if err := r.run(ctx, nil, "fetch", "origin", "+"+snapshot+":"+snapshot); err != nil {
		return fmt.Errorf("fetch workspace snapshot %q: %w", snapshot, err)
	}
	parent, err := r.output(ctx, r.dir, nil, "rev-parse", "--verify", snapshot+"^")
	if err != nil {
		return fmt.Errorf("resolve workspace snapshot parent: %w", err)
	}
	resolved, err := r.output(ctx, r.dir, nil, "rev-parse", "--verify", base+"^{commit}")
	if err != nil {
		return fmt.Errorf("resolve workspace base commit: %w", err)
	}
	if parent != resolved {
		return fmt.Errorf("workspace snapshot %q is not based on %s", snapshot, base)
	}
	if err := r.run(ctx, nil, "reset", "--hard", base); err != nil {
		return err
	}
	// The snapshot's tree onto the working tree alone: changed and new files
	// written, deleted ones removed, the index left at the base so all of it
	// reads as unstaged. Unlike applying a patch it does not care what is
	// already there, so a retry after an interruption lands the same way.
	if err := r.run(ctx, nil, "restore", "--source="+snapshot, "--worktree", "--", ":/"); err != nil {
		return fmt.Errorf("restore workspace snapshot: %w", err)
	}
	return nil
}

// configureUpstream adds the remote the client's own checkout tracks. It is
// written once, at materialization: it is a starting point, and whoever works
// in the sandbox owns it afterwards.
func (r *repository) configureUpstream(ctx context.Context, upstreamURL string) error {
	upstreamURL = strings.TrimSpace(upstreamURL)
	if upstreamURL == "" {
		return nil
	}
	if err := r.run(ctx, nil, "config", "--replace-all", "remote."+upstreamRemote+".url", upstreamURL); err != nil {
		return err
	}
	return r.run(ctx, nil, "config", "--replace-all", "remote."+upstreamRemote+".fetch", "+refs/heads/*:refs/remotes/"+upstreamRemote+"/*")
}

// ensureOrigin points origin at originURL, gives it the default refspec when
// it has none, and has its credentials read from this agent. It is asserted on
// every pass, because the remote belongs to the sandbox and not to the clone
// that made it — and the pool may serve the origin somewhere new. A refspec
// someone set by hand is theirs and is left alone.
func (r *repository) ensureOrigin(ctx context.Context, originURL, helper string) error {
	if err := r.ensureConfig(ctx, configSetting{"remote.origin.url", []string{originURL}}); err != nil {
		return err
	}
	fetch, err := r.configValues(ctx, "remote.origin.fetch")
	if err != nil {
		return err
	}
	if len(fetch) == 0 {
		if err := r.run(ctx, nil, "config", "--add", "remote.origin.fetch", "+refs/heads/*:refs/remotes/origin/*"); err != nil {
			return err
		}
	}
	if helper == "" {
		return nil
	}
	for _, setting := range credentialConfig(originURL, helper) {
		if err := r.ensureConfig(ctx, setting); err != nil {
			return err
		}
	}
	return nil
}

// configSetting is one configuration key and every value it is to hold, in
// order.
type configSetting struct {
	key    string
	values []string
}

// credentialConfig is the configuration that hands an origin's credentials to
// the agent's helper alone. The empty helper first clears every helper
// configured before this one — a user's `credential.helper store` included,
// which would otherwise be handed the token to keep — and useHttpPath has git
// name the origin's path, which is what tells one source's origin from
// another's on the same host.
func credentialConfig(originURL, helper string) []configSetting {
	section := "credential." + originURL
	return []configSetting{
		{section + ".helper", []string{"", helper}},
		{section + ".useHttpPath", []string{"true"}},
	}
}

// ensureConfig makes a key hold exactly the setting's values, rewriting it
// only when it differs, so an unchanged repository is not touched.
func (r *repository) ensureConfig(ctx context.Context, setting configSetting) error {
	current, err := r.configValues(ctx, setting.key)
	if err != nil {
		return err
	}
	if slices.Equal(current, setting.values) {
		return nil
	}
	if len(current) > 0 {
		if err := r.run(ctx, nil, "config", "--unset-all", setting.key); err != nil {
			return err
		}
	}
	for _, value := range setting.values {
		if err := r.run(ctx, nil, "config", "--add", setting.key, value); err != nil {
			return err
		}
	}
	return nil
}

// configValues reads a key's values; an unset key is none, not an error.
func (r *repository) configValues(ctx context.Context, key string) ([]string, error) {
	out, err := r.rawOutput(ctx, r.dir, nil, "config", "--null", "--get-all", key)
	if err != nil {
		var exit *exec.ExitError
		if errors.As(err, &exit) && exit.ExitCode() == 1 {
			return nil, nil
		}
		return nil, err
	}
	values := strings.Split(string(out), "\x00")
	return values[:len(values)-1], nil
}

// head is the commit checked out, empty when there is none.
func (r *repository) head(ctx context.Context) string {
	out, err := r.output(ctx, r.dir, nil, "rev-parse", "--verify", "--quiet", "HEAD")
	if err != nil {
		return ""
	}
	return out
}

// writeMarker creates a marker file holding content, owned by the checkout's
// owner as everything else in its .git is.
func (r *repository) writeMarker(path, content string) error {
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		return err
	}
	if r.owner == nil {
		return nil
	}
	return chownTo(path, r.owner)
}

func (r *repository) run(ctx context.Context, stdin []byte, args ...string) error {
	_, err := r.rawOutput(ctx, r.dir, stdin, args...)
	return err
}

func (r *repository) output(ctx context.Context, dir string, stdin []byte, args ...string) (string, error) {
	out, err := r.rawOutput(ctx, dir, stdin, args...)
	return strings.TrimSpace(string(out)), err
}

// rawOutput runs git in dir as the checkout's owner, with the sandbox's
// environment and never a prompt: there is nobody to answer one.
func (r *repository) rawOutput(ctx context.Context, dir string, stdin []byte, args ...string) ([]byte, error) {
	cmd := exec.CommandContext(ctx, "git", args...) //nolint:gosec // fixed subcommands; refs, URLs and paths are argv, never a shell.
	cmd.Dir = dir
	attr, err := execs.AgentSysProcAttr(r.owner)
	if err != nil {
		return nil, err
	}
	cmd.SysProcAttr = attr
	env := execs.EnvWithRuntimeDefaults(r.env, r.owner)
	env["GIT_TERMINAL_PROMPT"] = "0"
	cmd.Env = make([]string, 0, len(env))
	for key, value := range env {
		cmd.Env = append(cmd.Env, key+"="+value)
	}
	if stdin != nil {
		cmd.Stdin = bytes.NewReader(stdin)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		name := gitSubcommand(args)
		if msg := strings.TrimSpace(stderr.String()); msg != "" {
			return stdout.Bytes(), fmt.Errorf("git %s: %w: %s", name, err, msg)
		}
		return stdout.Bytes(), fmt.Errorf("git %s: %w", name, err)
	}
	return stdout.Bytes(), nil
}

// gitSubcommand names a git invocation by its subcommand, past any -c.
func gitSubcommand(args []string) string {
	for i := 0; i < len(args); i++ {
		if args[i] == "-c" {
			i++
			continue
		}
		return args[i]
	}
	return ""
}

