package sandboxruntime

import (
	"context"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	cerrdefs "github.com/containerd/errdefs"
	"github.com/moby/moby/client"

	workerapimodel "github.com/discobox-ai/discobox/pool-agent/api/model"
	"github.com/discobox-ai/discobox/pool-agent/proxyagent"
	"github.com/discobox-ai/discobox/pool-agent/sandboxtoken"
	"github.com/discobox-ai/discobox/sandboxconfig"
	"github.com/discobox-ai/discobox/sandboxuser"
)

// A sandbox materializes its own sources (ADR 0126 §4): the pool says, in the
// runtime-config document, where each source's origin is served, what is
// pinned and where its checkout belongs, and the sandbox agent clones it,
// as the checkout's owner, in its own namespace. The pool runs no git in a
// sandbox's checkout and binds no origin into it.
//
// What the pool still owns is settling (ADR 0055): a sandbox's spec is final
// only once its primary source's project layer has been read, and a source is
// marked delivered — which is what opens the sandbox's readiness gate — only
// then. The layer is read by asking the sandbox, never by reading its tree.

const (
	// originTokenTTL is how long a source's origin token lives, and
	// originTokenRenewBefore how close to its end the pool issues the next.
	// Deciding the document renews it, and the status poll decides it every
	// fifteen seconds for a running sandbox, so a token is replaced long
	// before a fetch could meet an expired one.
	originTokenTTL         = 24 * time.Hour
	originTokenRenewBefore = 12 * time.Hour

	// sourceStatePollInterval is how often a create asks the sandbox how far
	// its sources have converged while it waits for them.
	sourceStatePollInterval = 500 * time.Millisecond
	// sourceSettleTimeout bounds that wait. It outlasts the sandbox agent's
	// own bound on one source's clone, so the agent's verdict arrives first.
	sourceSettleTimeout = 35 * time.Minute
	// sourceWaitingTimeout bounds a source the sandbox has not begun to clone
	// at all: its agent tries as soon as a document names it, so one that is
	// still waiting this long after has an origin with nothing in it.
	sourceWaitingTimeout = 2 * time.Minute
	// sourceFailureLimit is how many attempts in a row the sandbox may fail
	// to clone a source before the create gives up on it. The agent goes on
	// retrying either way; a create that waits on a source that will not come
	// fails rather than hanging.
	sourceFailureLimit = 3

	// sandboxLabelProjectLayer is the digest of the project layer a
	// container's bootstrap was built from, empty for none. Settling compares
	// it with the layer the sandbox reads from its delivered source: the
	// container says what it was built from, so a rebuild that failed part way
	// is still seen as owed.
	sandboxLabelProjectLayer = "discobox.project_layer"
)

// Source states as the sandbox agent reports them
// (sandbox-agent/sourceconverge).
const (
	sourceStateWaiting      = "waiting"
	sourceStateMaterialized = "materialized"
	sourceStateFailed       = "failed"
)

// sourceState is one source's convergence as the sandbox reports it.
type sourceState struct {
	Slug      string    `json:"slug"`
	State     string    `json:"state"`
	Commit    string    `json:"commit,omitempty"`
	Error     string    `json:"error,omitempty"`
	Revision  int64     `json:"revision"`
	UpdatedAt time.Time `json:"updatedAt"`
}

// runtimeSources is the sandbox's sources as its document names them: where
// each checkout belongs, where its origin is served, and its pin. Whether each
// has been delivered, and its origin token, are carried over from prior, the
// document as recorded: a source is delivered once, and a token is the
// decision's to renew (refreshOriginTokens).
func (r *DockerSandboxRuntime) runtimeSources(sandboxID string, sources []sandboxSource, prior []sandboxconfig.RuntimeSource) []sandboxconfig.RuntimeSource {
	before := make(map[string]sandboxconfig.RuntimeSource, len(prior))
	for _, source := range prior {
		before[source.Slug] = source
	}
	out := make([]sandboxconfig.RuntimeSource, 0, len(sources))
	for _, source := range sources {
		origin := r.sourceOriginURL(sandboxID, source)
		next := sandboxconfig.RuntimeSource{
			Slug:      source.slug,
			Target:    source.target,
			OriginURL: origin,
			Commit:    sourceBaseCommit(source.git),
			Delivered: before[source.slug].Delivered,
		}
		if previous := before[source.slug]; previous.OriginURL == origin {
			next.OriginToken = previous.OriginToken
		}
		out = append(out, next)
	}
	return out
}

// sourceOriginURL is where the sandbox fetches a source from: this pool's
// git-origins route, at the origins host its proxy answers, for a source the
// client delivers from its own machine — live from the developer's Git
// directory, or the bare origin it pushes into — and the remote itself for a
// remote-URL source.
func (r *DockerSandboxRuntime) sourceOriginURL(sandboxID string, source sandboxSource) string {
	if poolServesOrigin(source.git) {
		return proxyagent.OriginURL(r.projectID, r.poolID, sandboxID, source.slug)
	}
	if remote, ok := source.git.URL.Get(); ok {
		return remote.String()
	}
	return ""
}

// poolServesOrigin reports whether a source's origin is this pool's to serve:
// one pushed into the pool, or one in a directory on the client's machine.
func poolServesOrigin(source workerapimodel.GitSource) bool {
	return gitSourceAwaitsPush(source) || strings.TrimSpace(optString(source.LocalDirectory)) != ""
}

// refreshOriginTokens gives every source whose origin this pool serves a token
// that fetches it, keeping the one the document holds until it is near its
// end. The token is this pool's sandbox token, scope origin:fetch, which reads
// this sandbox's origins and nothing else (sandboxtoken).
func (r *DockerSandboxRuntime) refreshOriginTokens(sandboxID string, doc *sandboxconfig.RuntimeConfig) error {
	if len(r.identityKey) == 0 {
		return nil
	}
	var verifier *sandboxtoken.Verifier
	for i := range doc.Sources {
		source := &doc.Sources[i]
		if !strings.HasPrefix(source.OriginURL, "https://"+proxyagent.OriginsHost+"/") {
			source.OriginToken = ""
			continue
		}
		if source.OriginToken != "" {
			if verifier == nil {
				public, _ := r.identityKey.Public().(ed25519.PublicKey)
				v, err := sandboxtoken.NewVerifier(public)
				if err != nil {
					return err
				}
				verifier = v
			}
			if claims, err := verifier.Verify(source.OriginToken); err == nil &&
				claims.SandboxID == sandboxID && time.Until(claims.Expires) > originTokenRenewBefore {
				continue
			}
		}
		token, err := sandboxtoken.Issue(r.identityKey, sandboxtoken.Claims{
			ProjectID: r.projectID,
			PoolID:    r.poolID,
			SandboxID: sandboxID,
			Scopes:    []string{sandboxtoken.ScopeOriginFetch},
		}, originTokenTTL)
		if err != nil {
			return fmt.Errorf("issue origin token for source %q: %w", source.Slug, err)
		}
		source.OriginToken = REDACTED
	}
	return nil
}

// settleSources finishes a create whose container is up: it waits for the
// sandbox to materialize every source its document names, reads the primary
// source's project layer from it, and either marks the sources delivered —
// which opens the sandbox's readiness gate — or reports that the container
// has to be rebuilt against a bootstrap that carries that layer (ADR 0055).
// The layer it read is recorded first, so the rebuild uses it.
//
// Nothing is settled while a push-delivered source's origin is still empty:
// the sandbox parks, and the resume create after the client's push settles it.
// A sandbox that is not running is left to the convergence after its next
// start (settleConverged), since only a running sandbox can answer.
func (r *DockerSandboxRuntime) settleSources(ctx context.Context, sb *Sandbox, req *workerapimodel.PoolSandboxCreateRequest) (bool, error) {
	sandboxID := sb.SandboxID
	doc, ok, err := r.readRuntimeConfig(sandboxID)
	if err != nil || !ok || doc.SourcesDelivered() || sb.Status != StatusRunning {
		return false, err
	}
	sources := sandboxSources(r.paths, req)

	sources := sandboxSources(r.paths, req)
	landed, err := r.pushedSourcesLanded(ctx, sandboxID, sources, resolveSandboxUser(r.paths, req))
	if err != nil || !landed {
		return false, err
	}
	// Delivered again, so a sandbox whose agent is backing off from an origin
	// that was empty until now goes again at once: a delivery wakes it, the
	// same document or not.
	if err := r.deliverRuntimeConfig(ctx, sandboxID, nil); err != nil {
		if errors.Is(err, ErrRuntimeConfigUnsupported) || errors.Is(err, ErrRuntimeConfigRefused) {
			return false, err
		}
		slog.WarnContext(ctx, "deliver sandbox runtime config before settling its sources", "sandboxId", sandboxID, "error", err)
	}
	dial, err := r.SandboxDialer(ctx, sandboxID, SandboxAgentPort)
	if err != nil {
		return false, err
	}
	if err := r.awaitSourcesMaterialized(ctx, dial, sandboxID, doc.Sources); err != nil {
		return false, err
	}
	built, err := r.containerProjectLayerDigest(ctx, sb.ID)
	if err != nil {
		return false, err
	}
	// The primary's slug is the request's, not the record's: a record from
	// before it named the slug names none.
	primary := ""
	if _, hasPrimary := req.Config.Source.Get(); hasPrimary {
		primary = sources[0].slug
	}
	rebuild, err := r.settleProjectLayer(ctx, dial, sandboxID, primary, built)
	if err != nil || rebuild {
		return rebuild, err
	}
	return false, r.markSourcesDelivered(ctx, sandboxID)
}

// settleConverged is settleSources for a running sandbox no create is waiting
// on — one started rather than created, such as an unarchived or imported
// sandbox, or a sandbox whose create stopped short of settling. The status
// poll calls it through ConvergeRuntimeConfig while the record names a source
// not yet delivered. It does not wait: a source the sandbox has not
// materialized yet is looked at again on the next poll. With no create
// request in hand it cannot rebuild the container itself, so a project layer
// that needs one removes the container for the control plane to recreate,
// on the bootstrap the recorded layer now gives it.
func (r *DockerSandboxRuntime) settleConverged(ctx context.Context, sb *Sandbox) error {
	doc, ok, err := r.readRuntimeConfig(sb.SandboxID)
	if err != nil || !ok || doc.SourcesDelivered() {
		return err
	}
	dial, err := r.SandboxDialer(ctx, sb.SandboxID, SandboxAgentPort)
	if err != nil {
		return err
	}
	states, err := r.readSourceStates(ctx, dial, sb.SandboxID)
	if errors.Is(err, ErrSourceStatesUnsupported) {
		// Nothing this poll can do; the create that rebuilds the sandbox on a
		// current image says so.
		return nil
	}
	if err != nil {
		return err
	}
	for _, source := range doc.Sources {
		if states[source.Slug].State != sourceStateMaterialized {
			return nil
		}
	}
	// The sandbox may have cloned a pushed source the moment the push landed,
	// before the create that resumes it: its origin's HEAD has to name what
	// arrived before the source is settled, as the resume would have made it.
	if err := r.headPushedOrigins(ctx, sb.SandboxID, doc.Sources); err != nil {
		return err
	}
	built, err := r.containerProjectLayerDigest(ctx, sb.ID)
	if err != nil {
		return err
	}
	record, err := r.readProjectLayerRecord(sb.SandboxID)
	if err != nil || record.Source == nil {
		return err
	}
	rebuild, err := r.settleProjectLayer(ctx, dial, sb.SandboxID, *record.Source, built)
	if err != nil {
		return err
	}
	if !rebuild {
		return r.markSourcesDelivered(ctx, sb.SandboxID)
	}
	slog.InfoContext(ctx, "removing a sandbox container whose delivered source declares project configuration it was not built with; the control plane rebuilds it", "sandboxId", sb.SandboxID)
	return r.removeForRebuild(ctx, sb)
}

// settleProjectLayer reads the primary source's project layer from a sandbox
// whose sources are all materialized — none when primary, its slug, is empty
// — and reports whether the container, built with the layer whose digest is
// built, has to be rebuilt for it. A layer that calls for a rebuild is
// recorded, so the rebuild's bootstrap carries it.
func (r *DockerSandboxRuntime) settleProjectLayer(ctx context.Context, dial Dialer, sandboxID, primary, built string) (bool, error) {
	var layer *sandboxconfig.ProjectLayer
	if primary != "" {
		var err error
		if layer, err = r.readSourceProjectLayer(ctx, dial, sandboxID, primary); err != nil {
			return false, err
		}
	}
	if projectLayerDigest(layer) == built {
		return false, nil
	}
	return true, r.writeProjectLayerRecord(sandboxID, projectLayerRecord{Project: layer, Source: &primary})
}

// markSourcesDelivered tells the sandbox its spec is final and its sources
// delivered, which is what clears its readiness gate (ADR 0055).
func (r *DockerSandboxRuntime) markSourcesDelivered(ctx context.Context, sandboxID string) error {
	return logRuntimeConfigFailure(ctx, sandboxID, r.deliverRuntimeConfig(ctx, sandboxID, func(doc *sandboxconfig.RuntimeConfig) {
		for i := range doc.Sources {
			doc.Sources[i].Delivered = true
		}
	}))
}

// pushedSourcesLanded reports whether every push-delivered source's origin
// holds the client's push, and gives each one that does the HEAD its clone
// reads. It runs git in the pool's own bare origin, never in the sandbox's
// checkout.
func (r *DockerSandboxRuntime) pushedSourcesLanded(ctx context.Context, sandboxID string, sources []sandboxSource, user sandboxuser.User) (bool, error) {
	for _, source := range sources {
		if !gitSourceAwaitsPush(source.git) {
			continue
		}
		origin := r.sandboxOriginPath(sandboxID, source.slug)
		uid, gid := chownID(user.UID), chownID(user.GID)
		if !gitOriginHasRefs(ctx, origin, uid, gid) {
			// The client has not pushed yet: the sandbox parks until the push
			// is reported complete and create runs again (ADR 0001 §4).
			return false, nil
		}
		if err := ensureOriginHead(ctx, origin, source.git, uid, gid); err != nil {
			return false, fmt.Errorf("source %q origin: %w", source.slug, err)
		}
	}
	return true, nil
}

// headPushedOrigins points the HEAD of each of the sandbox's bare origins that
// has received a push at what arrived, as the origin's owner
// (headOriginAtWhatArrived). A source with no bare origin is not pushed.
func (r *DockerSandboxRuntime) headPushedOrigins(ctx context.Context, sandboxID string, sources []sandboxconfig.RuntimeSource) error {
	for _, source := range sources {
		origin := r.sandboxOriginPath(sandboxID, source.Slug)
		info, err := os.Stat(origin)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return err
		}
		uid, gid := fileOwner(info)
		if err := headOriginAtWhatArrived(ctx, origin, uid, gid); err != nil {
			return fmt.Errorf("source %q origin: %w", source.Slug, err)
		}
	}
	return nil
}

// ErrSourceStatesUnsupported is a sandbox agent that cannot say how far its
// sources have converged: an image whose agent predates the route, or one with
// no source converger. Waiting on it would wait forever.
var ErrSourceStatesUnsupported = errors.New("the sandbox's image predates cloning its own sources; rebuild it on a current discobox base")

// awaitSourcesMaterialized waits until the sandbox reports every source named
// materialized. A source whose clone keeps failing, or that the sandbox never
// starts on, fails the wait with what the sandbox said.
func (r *DockerSandboxRuntime) awaitSourcesMaterialized(ctx context.Context, dial Dialer, sandboxID string, sources []sandboxconfig.RuntimeSource) error {
	ctx, cancel := context.WithTimeout(ctx, sourceSettleTimeout)
	defer cancel()
	start := time.Now()
	// The first failure seen may be from before this wait woke the agent, so
	// only a failure reported later counts, and only a run of them.
	firstSeen := map[string]sourceState{}
	failures := map[string]int{}
	for {
		states, err := r.readSourceStates(ctx, dial, sandboxID)
		if errors.Is(err, ErrSourceStatesUnsupported) {
			return fmt.Errorf("sandbox %s: %w", sandboxID, err)
		}
		if err != nil {
			slog.WarnContext(ctx, "read sandbox source states", "sandboxId", sandboxID, "error", err)
		}
		pending := 0
		for _, source := range sources {
			state, ok := states[source.Slug]
			if ok && state.State == sourceStateMaterialized {
				continue
			}
			pending++
			if !ok {
				continue
			}
			first, seen := firstSeen[source.Slug]
			if !seen {
				firstSeen[source.Slug] = state
				first = state
			}
			switch {
			case state.State == sourceStateFailed && !state.UpdatedAt.Equal(first.UpdatedAt):
				failures[source.Slug]++
				firstSeen[source.Slug] = state
				if failures[source.Slug] >= sourceFailureLimit {
					return fmt.Errorf("materialize source %q: %s", source.Slug, state.Error)
				}
			case state.State == sourceStateWaiting && time.Since(start) > sourceWaitingTimeout:
				return fmt.Errorf("materialize source %q: its origin %s has nothing to clone", source.Slug, source.OriginURL)
			}
		}
		if pending == 0 {
			return nil
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("wait for the sandbox to materialize its sources: %w", ctx.Err())
		case <-time.After(sourceStatePollInterval):
		}
	}
}

// readSourceStates asks the sandbox how far each source has converged.
func (r *DockerSandboxRuntime) readSourceStates(ctx context.Context, dial Dialer, sandboxID string) (map[string]sourceState, error) {
	var body struct {
		Sources []sourceState `json:"sources"`
	}
	if err := r.getFromSandboxAgent(ctx, dial, sandboxID, "/sources", &body); err != nil {
		return nil, err
	}
	out := make(map[string]sourceState, len(body.Sources))
	for _, state := range body.Sources {
		out[state.Slug] = state
	}
	return out, nil
}

// readSourceProjectLayer asks the sandbox for a materialized source's project
// layer, nil when the source has none (ADR 0012 §7).
func (r *DockerSandboxRuntime) readSourceProjectLayer(ctx context.Context, dial Dialer, sandboxID, slug string) (*sandboxconfig.ProjectLayer, error) {
	var body struct {
		ProjectLayer json.RawMessage `json:"projectLayer"`
	}
	if err := r.getFromSandboxAgent(ctx, dial, sandboxID, "/sources/"+slug+"/project-layer", &body); err != nil {
		return nil, fmt.Errorf("read source %q project layer: %w", slug, err)
	}
	if len(body.ProjectLayer) == 0 || string(body.ProjectLayer) == "null" {
		return nil, nil
	}
	var layer sandboxconfig.ProjectLayer
	if err := json.Unmarshal(body.ProjectLayer, &layer); err != nil {
		return nil, fmt.Errorf("parse source %q .discobox/project.json: %w", slug, err)
	}
	return &layer, nil
}

// getFromSandboxAgent reads one of the sandbox agent's runtime-config routes,
// with the token the pool signs for them (runtimeConfigToken).
func (r *DockerSandboxRuntime) getFromSandboxAgent(ctx context.Context, dial Dialer, sandboxID, route string, out any) error {
	ctx, cancel := context.WithTimeout(ctx, runtimeConfigCallTimeout)
	defer cancel()
	token, err := r.runtimeConfigToken(sandboxID)
	if err != nil {
		return err
	}
	target := HTTPURL(SandboxAgentPort, fmt.Sprintf("/api/projects/%s/sandboxes/%s%s", r.projectID, sandboxID, route))
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, target.String(), nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	resp, err := (&http.Client{Transport: dial.Transport()}).Do(req)
	if err != nil {
		return err

	}
	// Validated before any container work, so a malformed request costs nothing
	// and fails saying what was wrong with it.
	if err := validateCreateRequest(sandboxID, req); err != nil {
		return nil, err
	}
	// A create can start a container, so it waits out a cache clear and holds
	// one off until it is done (see clearcache.go).
	leave, err := r.starts.enter(ctx)
	if err != nil {
		return nil, err
	}
	defer leave()
	// Replacing a container is a power operation on this sandbox as much as a
	// start or a stop is, and it reads the power state it is preserving
	// (ADR 0021 §3). Taking the same per-sandbox lock is what stops an auto-start
	// (ADR 0017 §12) from racing the replacement — starting the container being
	// removed, or finding none at all.
	lock := r.sandboxLock(sandboxID)
	lock.Lock()
	defer lock.Unlock()
	// Before anything reads a source path: a sandbox from before the slug was
	// sent holds its sources under their old names, and every check below --
	// what is materialized, what is mounted, what the git route serves --
	// asks by slug.
	if err := r.adoptSourcePaths(ctx, sandboxID, sandboxSources(r.paths, req)); err != nil {
		return nil, err
	}
	// A container this create replaces takes its power state with it: an upgrade
	// restarts a running sandbox into the new image and leaves a stopped one
	// stopped (ADR 0021 §3).
	replacedRunning := false
	var replaced *Sandbox
	if existing, err := r.GetSandbox(ctx, sandboxID); err == nil {
		drifted, err := r.containerSpecDrifted(ctx, existing, req)
		if err != nil {
			return nil, err
		}
		// The control plane changed this sandbox's spec — an image upgrade
		// (ADR 0021 §1) or any other manifest edit.
		reason := "a spec change"
		if !drifted {
			// The container already exists, but a push-delivered source is only
			// materialized once the client has pushed, which necessarily happens
			// after the container was created and parked. This create is that
			// resume, so settle those sources rather than returning a sandbox
			// whose workspace is still empty.
			r.publishSandboxPhase(ctx, sandboxID, PhaseMaterializingSource)
			rebuild, err := r.settleSources(ctx, existing, req)
			if err != nil {
				return nil, err
			}
			if !rebuild {
				return existing, nil
			}
			reason = "the project configuration its delivered source declares"
		}
		// The container is replaced below, once the image the new one needs is
		// in hand; the sandbox's state lives in the pool-host binds prepared
		// below, not in the container, so it survives.
		replaced = existing
		replacedRunning = existing.Status == StatusRunning
		slog.InfoContext(ctx, "replacing sandbox container",
			"sandboxId", sandboxID,
			"reason", reason,
			"imageDigest", strings.TrimSpace(optString(req.Config.ImageDigest)),
			"specFingerprint", strings.TrimSpace(optString(req.Config.SpecFingerprint)),
			"running", replacedRunning)
	} else if !errors.Is(err, ErrNotFound) {
		return nil, err
	}
	// A container is built at most twice per create: once from the project
	// layer recorded so far, and once more when the sandbox, having cloned its
	// primary source, reads a different one from it (settleSources). The
	// rebuild records the layer it read, so a third would mean the layer
	// changed under the create, which is answered as a failure rather than a
	// loop.
	for builds := 0; ; builds++ {
		sb, rebuild, err := r.buildSandboxContainer(ctx, sandboxID, req, replaced, replacedRunning)
		if err != nil || !rebuild {
			return sb, err
		}
		if builds > 0 {
			return nil, fmt.Errorf("sandbox %s: its project layer changed again after the container was rebuilt for it", sandboxID)
		}
		slog.InfoContext(ctx, "replacing sandbox container", "sandboxId", sandboxID,
			"reason", "the project configuration its delivered source declares", "running", true)
		replaced, replacedRunning = sb, sb.Status == StatusRunning
	}
}

// buildSandboxContainer builds the sandbox's container, replacing replaced
// when there is one, and starts it when the create asks for that or the
// container it replaces was running. A container that started is settled on
// its sources before this returns (settleSources); it reports a rebuild when
// the project layer its primary source declares is not the one it was built
// with, and returns that container for the caller to replace.
func (r *DockerSandboxRuntime) buildSandboxContainer(ctx context.Context, sandboxID string, req *workerapimodel.PoolSandboxCreateRequest, replaced *Sandbox, replacedRunning bool) (*Sandbox, bool, error) {
	normalizeSandboxConfig(r.paths, &req.Config)
	// Before anything is stopped or pulled: a working directory that names no
	// place in the sandbox fails the create as the container runtime would
	// have, rather than after the running container is gone.
	workingDir, err := sourceWorkingDirectory(r.paths, req)
	if err != nil {
		return nil, false, err
	}
	config := req.Config
	imageName := strings.TrimSpace(optString(config.Image))
	imageName, err = r.resolveSandboxImage(ctx, sandboxID, imageName, strings.TrimSpace(optString(config.ImageDigest)))
	if err != nil {
		return nil, false, err
	}
	if replaced != nil {
		// Only now, with the new image on the host: obtaining it is the step a
		// re-pin fails at, and a sandbox that cannot get its new image keeps the
		// container it had rather than being left with none (ADR 26-10-01-876 §4).
		if replacedRunning {
			// Stop it the way a stop would, so the sandbox-agent tears its execs
			// down and flushes their logs instead of being killed outright.
			r.publishSandboxState(ctx, sandboxID, StateStopping)
			timeout := sandboxStopTimeoutSeconds
			if _, err := r.client.ContainerStop(ctx, replaced.ID, client.ContainerStopOptions{Timeout: &timeout}); err != nil && !cerrdefs.IsNotFound(err) {
				return nil, false, fmt.Errorf("stop sandbox container for a spec change: %w", err)
			}
		}
		if _, err := r.client.ContainerRemove(ctx, replaced.ID, client.ContainerRemoveOptions{Force: true}); err != nil && !cerrdefs.IsNotFound(err) {
			return nil, false, fmt.Errorf("remove sandbox container for a spec change: %w", err)
		}
	}
	user := resolveSandboxUser(r.paths, req)
	r.publishSandboxPhase(ctx, sandboxID, PhasePreparingVolumes)
	mounts, err := r.prepareSandboxVolumes(ctx, sandboxID, req, user)
	if err != nil {
		return nil, false, err
	}
	// The bootstrap is built from the project layer recorded for the sandbox:
	// none until it has cloned its primary source, and from then on the one
	// settling read from it (settleSources).
	project, err := r.readProjectLayerRecord(sandboxID)
	if err != nil {
		return nil, false, err
	}
	primary := ""
	if _, hasPrimary := req.Config.Source.Get(); hasPrimary {
		// The primary source is always first when present (sandboxSources).
		primary = sandboxSources(r.paths, req)[0].slug
	} else {
		// Only the primary source carries a project layer.
		project.Project = nil
	}
	project.Source = &primary
	if err := r.writeProjectLayerRecord(sandboxID, project); err != nil {
		return nil, false, err
	}
	proxyMaterial, err := proxyagent.EnsureSandboxMaterial(r.root, r.projectID, r.poolID, sandboxID)
	if err != nil {
		return nil, false, err
	}
	sentinels, _ := req.Sentinels.Get()
	if err := proxyagent.UpsertSandboxSentinels(r.root, r.projectID, r.poolID, sandboxID, sentinels); err != nil {
		return nil, false, err
	}
	// The bootstrap: placed before the container exists, and the one thing the
	// pool ever writes into the sandbox's config volume (ADR 0126 §3).
	if err := r.writeSandboxHarnessConfig(ctx, sandboxID, imageName, req, proxyMaterial.Env, project.Project); err != nil {
		return nil, false, err
	}
	// Everything else the sandbox is told is its runtime-config document,
	// delivered once its agent answers (finishBoot). The secrets the control
	// plane sends a create are the sandbox's whole set. Each source is named
	// with where its origin is, which the sandbox clones it from; it stays
	// undelivered until settling has read its project layer.
	secretEnv, _ := req.SecretEnv.Get()
	if err := r.recordRuntimeConfig(sandboxID, func(doc *sandboxconfig.RuntimeConfig) {
		doc.SecretEnv = cloneStringMap(secretEnv)
		doc.Sources = r.runtimeSources(sandboxID, sandboxSources(r.paths, req), doc.Sources)
	}); err != nil {
		return nil, false, err
	}
	baseEnv := mergeEnv(map[string]string(optSandboxConfigEnv(config.Env)), proxyMaterial.Env)
	name := sandboxContainerName(r.poolID, sandboxID)
	cfg := &container.Config{
		Image:        imageName,
		Hostname:     sandboxHostname(sandboxID),
		Labels:       r.labels(sandboxID, strings.TrimSpace(optString(config.SpecFingerprint)), projectLayerDigest(project.Project)),
		Env:          envList(envWithSandboxUser(baseEnv, user)),
		WorkingDir:   workingDir,
		AttachStdout: true,
		AttachStderr: true,
		Tty:          true,
	}
	hostCfg := &container.HostConfig{
		Mounts:     mounts,
		Privileged: true,
		// Docker's 64 MiB /dev/shm is too small for what a sandbox runs:
		// Chromium and Electron put their shared pixel buffers there, and on
		// the desktop's 3840x2432 display one frame is ~37 MiB, so VS Code's
		// renderer dies on start. The size is a tmpfs cap, not a reservation.
		ShmSize: r.sharedMemoryBytes,
		// Docker's embedded resolver answers container names itself and
		// forwards every other name here. On an internal network it forwards
		// nowhere else, so without this no external name resolves. The
		// address is the sandbox's own: its DNS stub claims it on loopback
		// and carries each query to the pool over mTLS.
		DNS: []netip.Addr{proxyagent.SandboxDNSAddress},
	}
	// No CPU/memory limit is set here: a sandbox container shares its pool
	// container's cgroup rather than reserving a nested slice of it
	// (ADR 0029).
	// Attach the sandbox to the per-pool internal network only: it reaches the
	// pool proxy (resolved as discobox-pool-proxy via Docker embedded DNS)
	// and the pool's DNS forwarder, but has no route off-box, so all egress is
	// forced through the proxy.
	netCfg := &network.NetworkingConfig{
		EndpointsConfig: map[string]*network.EndpointSettings{
			proxyagent.SandboxNetworkName(r.poolID): {},
		},
	}
	r.publishSandboxPhase(ctx, sandboxID, PhaseCreatingContainer)
	created, err := r.client.ContainerCreate(ctx, client.ContainerCreateOptions{Config: cfg, HostConfig: hostCfg, NetworkingConfig: netCfg, Name: name})
	if err != nil {
		return nil, false, err
	}
	// A create that is not asked to start leaves the container built and down.
	// That is what makes rebuilding a sandbox whose container was lost a
	// restoration rather than a resurrection: the sandbox exists again, and
	// whoever wants it running starts it (ADR 0017 §13).
	//
	// Replacing a running container is the exception, and the flag cannot veto
	// it: Start is first-create intent, not a desired power state for a sandbox
	// that already exists, so the two inputs only ever add a start (ADR 0021 §4).
	if !config.Start.Or(true) && !replacedRunning {
		sb, err := r.observedSandbox(ctx, sandboxID)
		return sb, false, err
	}
	r.publishSandboxState(ctx, sandboxID, StateStarting)
	r.publishSandboxPhase(ctx, sandboxID, PhaseStartingContainer)
	boot := r.beginBoot(sandboxID)
	if _, err := r.client.ContainerStart(ctx, created.ID, client.ContainerStartOptions{}); err != nil {
		r.endBoot(sandboxID, boot, err)
		return nil, false, err
	}
	// The container is up and the agent inside it is not yet answering. This is
	// the last phase the pool agent can see: what happens after it is the
	// sandbox agent's own boot, which reports on no channel this one owns
	// (ADR 0060).
	r.publishSandboxPhase(ctx, sandboxID, PhaseWaitingForAgent)
	if err := r.finishBoot(ctx, sandboxID, boot); err != nil {
		return nil, false, err
	}
	// The sandbox clones its sources now that its agent has the document
	// naming them, and the create settles on them before it returns, as a
	// pool that cloned them itself used to before the container existed.
	sb, err := r.GetSandbox(ctx, sandboxID)
	if err != nil {
		return nil, false, err
	}
	r.publishSandboxPhase(ctx, sandboxID, PhaseMaterializingSource)
	rebuild, err := r.settleSources(ctx, sb, req)
	if err != nil || rebuild {
		return sb, rebuild, err
	}
	sb, err = r.observedSandbox(ctx, sandboxID)
	return sb, false, err
}

// observedSandbox reads the sandbox back and reports what it sees before
// returning it.
//
// Every create ends here, including the one that was not asked to start
// anything. That create is the case the Docker event stream cannot cover: no
// container transition happens, so an unarchive or a rebuild after the
// container was lost would produce no observation at all and the control plane
// would carry its previous belief until the next complete sync, up to a full
// interval later (ADR 0034 §4).
//
// A create that did start the container publishes a state the `start` event
// already reported. That duplicate is harmless — the report is idempotent and
// carries a newer sequence — and it is worth more than the alternative, which
// is a create path where whether an observation gets published depends on which
// branch it took.
func (r *DockerSandboxRuntime) observedSandbox(ctx context.Context, sandboxID string) (*Sandbox, error) {
	sb, err := r.GetSandbox(ctx, sandboxID)
	if err != nil {
		return nil, err
	}
	r.publishSandboxState(ctx, sandboxID, stateFromStatus(sb.Status))
	return sb, nil
}

// resolveSandboxImage resolves what a sandbox must actually run and returns the
// image ID to launch it from.
//
// The pinned digest is the identity; the reference is only a way to obtain it
// (ADR 0016 §6). Launching the reference instead would let a rebuilt tag change
// a sandbox underneath its user — and, because containerImageDrifted compares
// against the pin, would make every such sandbox look drifted and be replaced
// silently, performing an upgrade nobody asked for. An empty pin means unpinned:
// resolve the reference and run whatever it names.
func (r *DockerSandboxRuntime) resolveSandboxImage(ctx context.Context, sandboxID, imageName, pinnedDigest string) (string, error) {
	if pinnedDigest != "" {
		// A pinned image already on the host is authoritative, whatever the tag
		// points at now.
		if inspected, err := r.client.ImageInspect(ctx, pinnedDigest); err == nil {
			return inspected.ID, nil
		} else if !cerrdefs.IsNotFound(err) {
			return "", err
		}
	}
	if err := r.ensureImageAvailable(ctx, sandboxID, imageName); err != nil {
		return "", err
	}
	inspected, err := r.client.ImageInspect(ctx, imageName)
	if err != nil {
		return "", fmt.Errorf("inspect image %q: %w", imageName, err)
	}
	if !imageMatchesPinDigests(inspected.ID, inspected.RepoDigests, pinnedDigest) {
		return "", fmt.Errorf(
			"%w: the sandbox is pinned to image %s but %q now resolves to %s, and the pinned image is not on this pool; upgrade the sandbox to move it to the current image",
			ErrImageUnavailable, pinnedDigest, imageName, inspected.ID)
	}
func (r *DockerSandboxRuntime) publishSandboxProgress(ctx context.Context, observation SandboxProgressObservation) {
	publish, _ := r.progressPublisher.Load().(func(context.Context, SandboxProgressObservation) error)
	if publish == nil || strings.TrimSpace(observation.SandboxID) == "" || strings.TrimSpace(observation.Phase) == "" {
		return
	}
	if err := publish(ctx, observation); err != nil {
		// Warn rather than Debug, unlike the state channel above. A dropped
		// state observation is repaired by the next complete sync; progress has
		// no sync behind it, so a report that fails is simply lost, and the
		// record a waiting client reads (ADR 0055) is silently wrong. The
		// agent's default handler drops Debug, which made exactly that
		// invisible.
		slog.WarnContext(ctx, "publish sandbox progress", "sandboxId", observation.SandboxID, "phase", observation.Phase, "error", err)
	}
}

// publishSandboxPullProgress reports the image pull, the one phase that can say
// how far in it is.
func (r *DockerSandboxRuntime) publishSandboxPullProgress(ctx context.Context, sandboxID string, pull PullProgress) {
	r.publishSandboxProgress(ctx, SandboxProgressObservation{SandboxID: sandboxID, Phase: PhasePullingImage, Pull: &pull})
}

// publishSandboxPhase reports a phase that has nothing to measure — which is
// every phase but the pull. It is the call the create path makes at each of its
// own boundaries.
func (r *DockerSandboxRuntime) publishSandboxPhase(ctx context.Context, sandboxID, phase string) {
	r.publishSandboxProgress(ctx, SandboxProgressObservation{SandboxID: sandboxID, Phase: phase})
}

// WatchSandboxProgress installs the progress sink for as long as ctx lives. It
// is separate from WatchSandboxStates because progress is reported by whoever
// is doing the work, not derived from the Docker event stream, so there is
// nothing here to watch — only a sink to hold.
func (r *DockerSandboxRuntime) WatchSandboxProgress(ctx context.Context, publish func(context.Context, SandboxProgressObservation) error) {
	if publish == nil {
		return
	}
	r.progressPublisher.Store(publish)
	defer r.progressPublisher.Store((func(context.Context, SandboxProgressObservation) error)(nil))
	<-ctx.Done()
}

// WatchSandboxStates runs the state channel until ctx ends.
func (r *DockerSandboxRuntime) WatchSandboxStates(ctx context.Context, logger *slog.Logger, publish func(context.Context, SandboxStateBatch) error) {
	if logger == nil {
		logger = slog.Default()
	}
	if publish == nil {
		return
	}
	r.statePublisher.Store(publish)
	defer r.statePublisher.Store((func(context.Context, SandboxStateBatch) error)(nil))

	for ctx.Err() == nil {
		if err := r.watchSandboxStateEvents(ctx, logger, publish); err != nil && ctx.Err() == nil {
			logger.Warn("watch sandbox state events", "error", err)
		}
		select {
		case <-ctx.Done():
			return
		case <-time.After(sandboxStateWatchBackoff):
		}
	}
}

